--
-- Table structure for table `sales`
--

DROP TABLE IF EXISTS `sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `invoice_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `customer_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mechanic_id` int(11) DEFAULT NULL,
  `subtotal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `discount_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `discount_approved_by` int(11) DEFAULT NULL,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_cogs` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gross_profit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gross_margin_percent` decimal(5,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `balance_due` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment_method` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Cash',
  `payment_status` enum('paid','partially_paid','unpaid','credit') COLLATE utf8mb4_unicode_ci DEFAULT 'paid',
  `sale_status` enum('completed','cancelled','refunded','partially_refunded') COLLATE utf8mb4_unicode_ci DEFAULT 'completed',
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credit_override_by` int(11) DEFAULT NULL,
  `credit_override_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cashier_id` int(11) NOT NULL,
  `sale_date` datetime NOT NULL,
  `due_date` date DEFAULT NULL,
  `payment_terms` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Cash only',
  `sales_channel` enum('POS','ONLINE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'POS',
  `online_order_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_no` (`invoice_no`),
  KEY `mechanic_id` (`mechanic_id`),
  KEY `discount_approved_by` (`discount_approved_by`),
  KEY `idx_sale_invoice` (`invoice_no`),
  KEY `idx_sale_date` (`sale_date`),
  KEY `idx_sale_customer` (`customer_id`),
  KEY `idx_sale_cashier` (`cashier_id`),
  KEY `fk_sales_credit_override` (`credit_override_by`),
  KEY `idx_sales_customer_date` (`customer_id`,`sale_date`),
  CONSTRAINT `fk_sales_credit_override` FOREIGN KEY (`credit_override_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `sales_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `sales_ibfk_2` FOREIGN KEY (`mechanic_id`) REFERENCES `mechanics` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `sales_ibfk_3` FOREIGN KEY (`discount_approved_by`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `sales_ibfk_4` FOREIGN KEY (`cashier_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=239 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

